        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc):
                continue

            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            path = [(r1 + k * sr, c1 + k * sc)
                    for k in range(abs(dr) + 1)]

            for r, c in path:
                if grid[r][c] != 6:
                    out[r][c] = 1

            for r, c in sixes:
                if (r, c) in path:
                    # Extend a diagonal perpendicular to the 1-to-1 path.
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != 1:
                            out[rr][cc] = 6
                        rr -= sr
                        cc += sc
                    rr, cc = r + sr, c - sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != 1:
                            out[rr][cc] = 6
                        rr += sr
                        cc -= sc

    return out
